+// formatDuration formats d with a fixed two decimal places and a unit
+// suffix padded to two characters, so that decimal points line up when
+// the values are right aligned in a column.
+func formatDuration(d time.Duration) string {
+	var (
+		div  float64
+		unit string
+	)
+	switch {
+	case d >= time.Second:
+		div, unit = float64(time.Second), "s"
+	case d >= time.Millisecond:
+		div, unit = float64(time.Millisecond), "ms"
+	case d >= time.Microsecond:
+		div, unit = float64(time.Microsecond), "µs"
+	default:
+		div, unit = 1, "ns"
+	}
+	return fmt.Sprintf("%.2f%-2s", float64(d)/div, unit)
+}
