+)
+
+// ApplyImportContext configures opts to resolve imports using the given import context
+// (e.g. set in resources.Copy) before falling back to the default import resolution.
+// Resolved resources are added to dependencyManager.
+// Note that this will overwrite any ImportOnResolveFunc, ImportOnLoadFunc,
+// ErrorMessageResolveFunc and ResolveSourceMapSource set in opts.
+func ApplyImportContext(ctx context.Context, opts *Options, importContext resource.ResourceGetter, dependencyManager identity.Manager) {
+	if importContext == nil {
+		return
+	}
+	if dependencyManager == nil {
+		dependencyManager = identity.NopManager
+	}
+
+	importResource := hmaps.NewCache[string, resource.Resource]()
+
+	opts.ImportOnResolveFunc = func(imp string, args api.OnResolveArgs) string {
+		if r, found := importResource.Get(imp); found {
+			dependencyManager.AddIdentity(identity.FirstIdentity(r))
+			return imp
+		}
+		resolved := ResolveResource(imp, importContext)
+		if resolved == nil {
+			return ""
+		}
+		dependencyManager.AddIdentity(identity.FirstIdentity(resolved))
+		resolvePath := PrefixHugoVirtual + paths.AddLeadingSlash(resources.InternalResourceTargetPath(resolved))
+		importResource.Set(resolvePath, resolved)
+		return resolvePath
+	}
+
+	opts.ImportOnLoadFunc = func(args api.OnLoadArgs) (string, error) {
+		if r, found := importResource.Get(args.Path); found {
+			content, err := resources.InternalResourceSourceContent(ctx, r)
+			if err != nil {
+				return "", fmt.Errorf("failed to read import %q: %w", resources.InternalResourceSourcePathBestEffort(r), err)
+			}
+			return content, nil
+		}
+		return "", nil
+	}
+
+	opts.ErrorMessageResolveFunc = func(args api.Message) *ErrorMessageResolved {
+		if loc := args.Location; loc != nil {
+			path := strings.TrimPrefix(loc.File, NsHugoImportResolveFunc+":")
+			if r, found := importResource.Get(path); found {
+				var contentr hugio.ReadSeekCloser
+				if cp, ok := r.(hugio.ReadSeekCloserProvider); ok {
+					contentr, _ = cp.ReadSeekCloser()
+				}
+				return &ErrorMessageResolved{
+					Content: contentr,
+					Path:    resources.InternalResourceSourcePathBestEffort(r),
+					Message: args.Text,
+				}
+			}
+		}
+		return nil
+	}
+
+	opts.ResolveSourceMapSource = func(s string) string {
+		if r, found := importResource.Get(s); found {
+			if ss := resources.InternalResourceSourcePath(r); ss != "" {
+				return ss
+			}
+			return PrefixHugoMemory + s
+		}
+		return ""
+	}
+}
