+func TestCopyImportContextCSSBuild(t *testing.T) {
+	t.Parallel()
+
+	files := `
+-- hugo.toml --
+disableKinds = ['page','section','rss','sitemap','taxonomy','term']
+-- assets/css/main.css --
+@import "foo.css" screen;
+@import "bar.css" print;
+@import "assetsonly.css";
+.main { color: red; }
+-- assets/css/assetsonly.css --
+.assetsonly { color: black; }
+-- assets/css/bar.css --
+.bar-from-assets { color: black; }
+-- layouts/home.html --
+{{ $foo := resources.FromString "foo.css" ".foo { color: blue; }" }}
+{{ $bar := resources.FromString "bar.css" ".bar { color: green; }" }}
+{{ $main := resources.Get "css/main.css" | resources.Copy (dict "importContext" (slice $foo $bar)) }}
+{{ with $main | css.Build }}main: {{ .RelPermalink }}|{{ end }}
+{{ $main2 := resources.Get "css/main.css" | resources.Copy (dict "targetPath" "css/main2.css" "importContext" (slice $foo)) }}
+{{ with $main2 | css.Build }}main2: {{ .RelPermalink }}|{{ end }}
+`
+
+	b := hugolib.Test(t, files, hugolib.TestOptOsFs())
+
+	b.AssertFileContent("public/index.html", "main: /css/main.css|", "main2: /css/main2.css|")
+	b.AssertFileContent("public/css/main.css",
+		"@media screen {\n  .foo {",
+		"@media print {\n  .bar {\n    color: green;",
+		".assetsonly",
+		".main",
+		"! .bar-from-assets",
+	)
+	// Different import context, bar.css resolved from /assets.
+	b.AssertFileContent("public/css/main2.css",
+		"@media screen {\n  .foo {",
+		".bar-from-assets",
+		"! color: green",
+	)
+}
