+func TestCopyImportContextJSBuildPageResources(t *testing.T) {
+	t.Parallel()
+
+	files := `
+-- hugo.toml --
+disableKinds = ['section','rss','sitemap','taxonomy','term']
+-- assets/js/main.js --
+import { hello } from "lib/hello";
+import { common } from "common/common.js";
+console.log(hello(), common());
+-- assets/js/headlessui/common.js --
+export function common() { return "common from mount"; }
+-- content/p1/index.md --
+---
+title: p1
+---
+-- content/p1/lib/hello.js --
+export function hello() { return "hello from p1"; }
+-- content/p2/index.md --
+---
+title: p2
+---
+-- content/p2/lib/hello.js --
+export function hello() { return "hello from p2"; }
+-- layouts/home.html --
+Home.
+-- layouts/single.html --
+{{ $common := (resources.Match "js/headlessui/*.*").Mount "/js/headlessui" "common" }}
+{{ $opts := dict "targetPath" (printf "js/%s.js" .File.ContentBaseName) "importContext" (slice . $common) }}
+{{ $js := resources.Get "js/main.js" | resources.Copy $opts | js.Build }}
+JS: {{ $js.RelPermalink }}|
+`
+
+	b := hugolib.Test(t, files, hugolib.TestOptOsFs())
+
+	b.AssertFileContent("public/p1/index.html", "JS: /js/p1.js|")
+	b.AssertFileContent("public/p2/index.html", "JS: /js/p2.js|")
+	b.AssertFileContent("public/js/p1.js", "hello from p1", "common from mount", "! hello from p2")
+	b.AssertFileContent("public/js/p2.js", "hello from p2", "common from mount", "! hello from p1")
+}
