+// The same target path and transformation, but different import contexts,
+// must not share cached transformation results.
+func TestCopyImportContextSameTargetPathDifferentContexts(t *testing.T) {
+	t.Parallel()
+
+	files := `
+-- hugo.toml --
+disableKinds = ['section','section','rss','sitemap','taxonomy','term']
+-- assets/css/main.css --
+@import "theme.css";
+-- content/blue/index.md --
+---
+title: blue
+---
+-- content/blue/theme.css --
+.theme { color: blue; }
+-- content/green/index.md --
+---
+title: green
+---
+-- content/green/theme.css --
+.theme { color: green; }
+-- layouts/home.html --
+{{ $main := resources.Get "css/main.css" }}
+{{ $c1 := $main | resources.Copy (dict "importContext" (site.GetPage "blue")) | css.Build (dict "minify" true) }}
+{{ $c2 := $main | resources.Copy (dict "importContext" (site.GetPage "green")) | css.Build (dict "minify" true) }}
+c1: {{ $c1.Content | safeCSS }}|
+c2: {{ $c2.Content | safeCSS }}|
+`
+
+	b := hugolib.Test(t, files, hugolib.TestOptOsFs())
+
+	b.AssertFileContent("public/index.html", "c1: .theme{color:#00f}\n|", "c2: .theme{color:green}\n|")
+}
+
+// Import context set on an already transformed resource, and no options at all.
+// Import contexts with the same paths but different content must not share cached results.
