+func TestCopyImportContextCSSBuildEdit(t *testing.T) {
+	t.Parallel()
+
+	files := `
+-- hugo.toml --
+disableKinds = ["taxonomy", "term", "rss", "section", "sitemap"]
+-- assets/css/main.css --
