+.theme { background: green; }
+-- layouts/all.html --
+All.
+-- layouts/single.html --
+{{ $main := resources.Get "css/main.css" | resources.Copy (dict "targetPath" "css/p1.css" "importContext" .) }}
+{{ with $main | css.Build (dict "minify" true) }}<link rel="stylesheet" href="{{ .RelPermalink }}" />{{ end }}
+`
+	b := hugolib.TestRunning(t, files, hugolib.TestOptOsFs())
