+	b.AssertFileContent("public/p1/index.html", `<link rel="stylesheet" href="/css/p1.css" />`)
+	b.AssertFileContent("public/css/p1.css", `.theme{background:green}.main{background:red}`)
+
+	// Edit the page resource resolved from the import context.
+	b.EditFileReplaceAll("content/p1/theme.css", "green", "blue").Build()
+	b.AssertFileContent("public/css/p1.css", `.theme{background:#00f}.main{background:red}`)
+
+	// Edit main.css.
+	b.EditFileReplaceAll("assets/css/main.css", "red", "yellow").Build()
+	b.AssertFileContent("public/css/p1.css", `.theme{background:#00f}.main{background:#ff0}`)
+}
