+func TestCopyImportContextErrors(t *testing.T) {
+	t.Parallel()
+
+	files := `
+-- hugo.toml --
+disableKinds = ['page','section','rss','sitemap','taxonomy','term']
+-- assets/css/main.css --
+.main { color: red; }
+-- layouts/home.html --
+{{ $main := resources.Get "css/main.css" | resources.Copy (dict "importContext" 42) }}
+`
+
+	b, err := hugolib.TestE(t, files)
+	b.Assert(err, qt.IsNotNil)
+	b.Assert(err.Error(), qt.Contains, "importContext: expected a Page, Resource, Resources mounted with .Mount or a slice of these, got int")
+
+	files = strings.ReplaceAll(files, `(dict "importContext" 42)`, `(dict "importContexts" (slice))`)
+	b, err = hugolib.TestE(t, files)
+	b.Assert(err, qt.IsNotNil)
+	b.Assert(err.Error(), qt.Contains, `failed to decode options`)
+	b.Assert(err.Error(), qt.Contains, `importContexts`)
+}
