+func TestCopyImportContextSass(t *testing.T) {
+	t.Parallel()
+
+	files := `
+-- hugo.toml --
+disableKinds = ['page','section','rss','sitemap','taxonomy','term']
+-- assets/scss/main.scss --
+@import "colors";
+@import "components/button";
+.main { color: $color; }
+-- assets/scss/components/_button.scss --
+.button-from-assets { color: black; }
+-- layouts/home.html --
+{{ $colors := resources.FromString "_colors.scss" "$color: blue;" }}
+{{ $button := resources.FromString "components/_button.scss" ".button { color: $color; }" }}
+{{ $main := resources.Get "scss/main.scss" | resources.Copy (dict "importContext" (slice $colors $button)) }}
+{{ with $main | css.Sass (dict "transpiler" "TRANSPILER") }}{{ .Content | safeCSS }}{{ end }}
+`
+
+	for _, transpiler := range []string{"libsass", "dartsass"} {
+		t.Run(transpiler, func(t *testing.T) {
+			if transpiler == "libsass" && !scss.Supports() {
+				t.Skip("libsass not supported")
+			}
+			if transpiler == "dartsass" && !dartsass.Supports() {
+				t.Skip("dartsass not supported")
+			}
+			b := hugolib.Test(t, replaceTranspiler(files, transpiler), hugolib.TestOptOsFs())
+			b.AssertFileContent("public/index.html", ".button", "color: blue", "! .button-from-assets")
+		})
+	}
+}
+
+func replaceTranspiler(files, transpiler string) string {
+	return strings.ReplaceAll(files, "TRANSPILER", transpiler)
+}
