+// fragmentKeywords returns the keywords for the given fragments,
+// the fragment identifiers and, if Tokenize is enabled, the individual words
+// of the heading titles.
+func (cfg IndexConfig) fragmentKeywords(fragments *tableofcontents.Fragments) []Keyword {
+	keywords := make([]Keyword, 0, len(fragments.Identifiers))
+	for _, id := range fragments.Identifiers {
+		keywords = append(keywords, FragmentKeyword(id))
+	}
+	if !cfg.Tokenize {
+		return keywords
+	}
+
+	// Each word is added once per document, so cardinalityThreshold
+	// operates on the number of documents using a word.
+	seen := make(map[string]bool)
+	fragments.Headings.Walk(func(h *tableofcontents.Heading) {
+		for _, token := range cfg.tokenizeHeadingTitle(h.Title) {
+			if !seen[token] {
+				seen[token] = true
+				keywords = append(keywords, fragmentTokenKeyword(token))
+			}
+		}
+	})
+
+	return keywords
+}
+
+// tokenizeHeadingTitle splits the given heading title, which may contain
+// sanitized HTML, into individual words.
+func (cfg IndexConfig) tokenizeHeadingTitle(title string) []string {
+	if title == "" {
+		return nil
+	}
+	s := html.UnescapeString(stripHTMLTags(title))
+	if cfg.ToLower {
+		s = strings.ToLower(s)
+	}
+	return strings.FieldsFunc(s, func(r rune) bool {
+		// Combining marks are part of words in e.g. Indic scripts and decomposed text.
+		return !unicode.IsLetter(r) && !unicode.IsNumber(r) && !unicode.IsMark(r)
+	})
+}
+
+// stripHTMLTags replaces all HTML tags in s with a space.
+func stripHTMLTags(s string) string {
+	if !strings.ContainsRune(s, '<') {
+		return s
+	}
+	var b strings.Builder
+	b.Grow(len(s))
+	inTag := false
+	for _, r := range s {
+		switch {
+		case r == '<':
+			inTag = true
+		case r == '>' && inTag:
+			inTag = false
+			b.WriteRune(' ')
+		case !inTag:
+			b.WriteRune(r)
+		}
+	}
+	return b.String()
+}
