+// Closing the dispatcher's input while inputJSON is blocked reading
+// surfaces io.ErrClosedPipe from Decode (since Go 1.27, Decoder.More no longer swallows it).
+func TestDispatcherInputJSONClosedPipe(t *testing.T) {
+	newDispatcher := func() *dispatcher[person, greeting] {
+		stdin := hugio.NewPipeReadWriteCloser()
+		stdout := hugio.NewPipeReadWriteCloser()
+		return &dispatcher[person, greeting]{
+			pending: make(map[uint32]*call[person, greeting]),
+			inOut: &inOut{
+				stdin:  stdin,
+				stdout: stdout,
+				dec:    json.NewDecoder(stdout),
+				enc:    json.NewEncoder(stdin),
+			},
+		}
+	}
+
+	run := func(d *dispatcher[person, greeting], closing bool) (*call[person, greeting], error) {
+		pending := &call[person, greeting]{donec: make(chan *call[person, greeting], 1)}
+		d.pending[1] = pending
+		errc := make(chan error, 1)
+		go func() {
+			errc <- d.inputJSON()
+		}()
+		d.closing = closing
+		if err := d.inOut.Close(); err != nil {
+			t.Fatal(err)
+		}
+		err := <-errc
+		return <-pending.donec, err
+	}
+
+	t.Run("Close", func(t *testing.T) {
+		c := qt.New(t)
+		pending, err := run(newDispatcher(), true)
+		c.Assert(err, qt.IsNil)
+		c.Assert(pending.err, qt.Equals, ErrShutdown)
+	})
+
+	t.Run("Unexpected close", func(t *testing.T) {
+		c := qt.New(t)
+		pending, err := run(newDispatcher(), false)
+		c.Assert(err, qt.Equals, io.ErrUnexpectedEOF)
+		c.Assert(pending.err, qt.Equals, io.ErrUnexpectedEOF)
+	})
+}
