+				for b.Loop() {
+					fn([]int{}, []int{})
+				}
+			})
+			b.Run("empty map", func(b *testing.B) {
+				for b.Loop() {
+					fn(map[string]int{}, map[string]int{})
+				}
+			})
+			// End of edge case benchmark
